<?php

declare(strict_types=1);

// Retiro — filtro anual e lista de passageiros. Somente terminal, PHP >= 8.1.
if (PHP_SAPI !== 'cli' && PHP_SAPI !== 'phpdbg') { http_response_code(403); exit; }
if (PHP_VERSION_ID < 80100) { fwrite(STDERR, "PHP 8.1 ou superior necessário.\n"); exit(1); }
$raiz = __DIR__;
$previa = in_array('--verificar', $argv, true);
if (in_array('--help', $argv, true) || in_array('--ajuda', $argv, true)) {
    echo "Uso: php aplicar_alteracao.php [--verificar]\n"; exit(0);
}
$patches = json_decode(base64_decode('', true), true, 512, JSON_THROW_ON_ERROR);
$conteudoNovo = base64_decode('', true);
$helper = 'mod/auth/RelatorioPassageirosEvento.php';
$alteracoes = [];
$originais = [];
$normalizar = static fn(string $s): string => str_replace("\r\n", "\n", $s);
function sintaxe(string $conteudo, string $path): void {
    try { token_get_all($conteudo, TOKEN_PARSE); }
    catch (ParseError $e) { throw new RuntimeException("Sintaxe inválida em $path: " . $e->getMessage()); }
}
function escreverTemporario(string $path, string $conteudo): string {
    $temp = tempnam(dirname($path), '.retiro-patch-');
    if ($temp === false) { throw new RuntimeException("Não foi possível preparar o arquivo: $path"); }
    if (file_put_contents($temp, $conteudo, LOCK_EX) !== strlen($conteudo)) { @unlink($temp); throw new RuntimeException("Falha ao gravar: $path"); }
    if (is_file($path)) { @chmod($temp, fileperms($path) & 0777); } else { @chmod($temp, 0644); }
    return $temp;
}
function gravar(string $path, string $conteudo): void {
    $temp = escreverTemporario($path, $conteudo);
    if (!@rename($temp, $path)) { @unlink($temp); throw new RuntimeException("Não foi possível substituir: $path"); }
}
function lerArquivo(string $path): string {
    $s = file_get_contents($path);
    if ($s === false) { throw new RuntimeException("Falha ao ler $path"); }
    return $s;
}
$backup = null;
$feitos = [];
$lock = null;
try {
    echo "=== RETIRO — FILTRO ANUAL E PDF DE PASSAGEIROS ===\n";
    foreach (['config/settings.php','mod/auth/RelatorioEventoExportacao.php'] as $necessario) {
        if (!is_file($raiz . '/' . $necessario)) { throw new RuntimeException("Coloque o instalador na raiz do Retiro. Arquivo ausente: $necessario"); }
    }
    foreach ($patches as $rel => $pares) {
        $path = $raiz . '/' . $rel;
        if (!is_file($path) || is_link($path)) { throw new RuntimeException("Arquivo ausente ou link simbólico: $rel"); }
        $original = lerArquivo($path);
        $atual = $normalizar($original);
        foreach ($pares as [$antes, $depois]) {
            // Verifica a versão aplicada antes da antiga, pois a nova pode incluir a âncora antiga.
            if (substr_count($atual, $depois) === 1) { continue; }
            if (substr_count($atual, $depois) > 1 || substr_count($atual, $antes) !== 1) {
                throw new RuntimeException("Conflito em $rel. Nenhum arquivo será modificado. A estrutura atual difere da esperada.");
            }
            $atual = str_replace($antes, $depois, $atual);
        }
        if (str_contains($original, "\r\n")) { $atual = str_replace("\n", "\r\n", $atual); }
        sintaxe($atual, $rel);
        if ($atual !== $original) { $originais[$rel] = $original; $alteracoes[$rel] = $atual; echo "[PRONTO] $rel\n"; }
        else { echo "[OK] Já atualizado: $rel\n"; }
    }
    $hp = $raiz . '/' . $helper;
    if (is_link($hp)) { throw new RuntimeException("Link simbólico não permitido: $helper"); }
    sintaxe($conteudoNovo, $helper);
    if (file_exists($hp)) {
        if (!is_file($hp) || $normalizar(lerArquivo($hp)) !== $normalizar($conteudoNovo)) { throw new RuntimeException("Conflito: $helper já existe com conteúdo diferente."); }
        echo "[OK] Já atualizado: $helper\n";
    } else { $originais[$helper] = null; $alteracoes = [$helper => $conteudoNovo] + $alteracoes; echo "[NOVO] $helper\n"; }
    if ($previa) { echo "[PRÉVIA] " . count($alteracoes) . " arquivo(s) a alterar. Nada foi modificado.\n"; exit(0); }
    if (!$alteracoes) { echo "[OK] Nenhuma alteração necessária.\n"; exit(0); }
    // A pasta de backup é externa à aplicação, protegida e exclusiva para esta execução.
    $baseBackup = rtrim(sys_get_temp_dir(), '/\\');
    $backup = $baseBackup . '/retiro-backup-passageiros-' . date('Ymd-His') . '-' . bin2hex(random_bytes(8));
    if (!mkdir($backup, 0700, false)) { throw new RuntimeException('Não foi possível criar o backup privado.'); }
    foreach ($originais as $rel => $orig) {
        if ($orig === null) { continue; }
        $dest = $backup . '/' . $rel;
        if (!is_dir(dirname($dest)) && !mkdir(dirname($dest), 0700, true)) { throw new RuntimeException('Falha ao preparar backup.'); }
        if (file_put_contents($dest, $orig, LOCK_EX) !== strlen($orig) || lerArquivo($dest) !== $orig) { throw new RuntimeException("Falha no backup: $rel"); }
        @chmod($dest, 0600);
    }
    echo "[BACKUP] $backup\n";
    // Confirma que ninguém modificou os arquivos enquanto a atualização era preparada.
    foreach ($originais as $rel => $orig) {
        $path = $raiz . '/' . $rel;
        if (($orig === null && file_exists($path)) || ($orig !== null && (!is_file($path) || lerArquivo($path) !== $orig))) {
            throw new RuntimeException("Arquivo alterado durante a preparação: $rel");
        }
        if (!is_writable(dirname($path))) { throw new RuntimeException("Sem permissão de escrita em: $rel"); }
    }
    foreach ($alteracoes as $rel => $conteudo) {
        $path = $raiz . '/' . $rel;
        gravar($path, $conteudo);
        $feitos[] = $rel;
        if (lerArquivo($path) !== $conteudo) { throw new RuntimeException("Falha na verificação de $rel"); }
        echo "[OK] Instalado: $rel\n";
    }
    echo "[OK] Atualização concluída. Banco de dados, SMTP, cron, Asaas e demais relatórios preservados.\n";
    echo "Teste em Administração > Relatórios > Exportação de eventos.\n";
} catch (Throwable $e) {
    fwrite(STDERR, '[ERRO] ' . $e->getMessage() . PHP_EOL);
    foreach (array_reverse($feitos) as $rel) {
        try {
            if ($originais[$rel] === null) { if (!unlink($raiz . '/' . $rel)) { throw new RuntimeException('Falha ao remover novo arquivo.'); } }
            else { gravar($raiz . '/' . $rel, $originais[$rel]); }
            echo "[RESTAURADO] $rel\n";
        } catch (Throwable $r) { fwrite(STDERR, '[ATENÇÃO] Restauração manual necessária: ' . $rel . ' — ' . $r->getMessage() . PHP_EOL); }
    }
    if ($backup !== null) { fwrite(STDERR, "Backup: $backup\n"); }
    exit(1);
}
